-- Repair/import the verified W804 Master 001–036.
-- Safe and idempotent: inserts only missing numbers; never overwrites existing records.
ON CONFLICT (number) DO NOTHING;

UPDATE w804_counter SET next_number = GREATEST(next_number, 37) WHERE singleton = true;

SELECT
  ('80410000-0000-4000-8000-' || lpad(r.number::text,12,'0'))::uuid,
  r.id,
  'repair-master',
  NULL,
  to_jsonb(r)
FROM w804_records r
WHERE r.number BETWEEN 1 AND 36
  AND r.id::text LIKE '80400000-0000-4000-8000-%'
ON CONFLICT (id) DO NOTHING;
